package operators

import (
	"fmt"
	"net"

	"github.com/fivetwenty-io/graft/internal/utils/netutil"
	graft "github.com/fivetwenty-io/graft/pkg/graft"
	"github.com/fivetwenty-io/graft/pkg/graft/tree"
)

// IpsOperator generates a list of IP addresses from a network specification.
type IpsOperator struct{}

// Setup ...
func (IpsOperator) Setup() error {
	return nil
}

// Phase ...
func (IpsOperator) Phase() OperatorPhase {
	return EvalPhase
}

// Dependencies ...
func (IpsOperator) Dependencies(ev *Evaluator, args []*Expr, locs []*tree.Cursor, auto []*tree.Cursor) []*tree.Cursor {
	l := []*tree.Cursor{}

	for _, arg := range args {
		switch arg.Type {
		case Reference:
			// arg.Reference is nil for a bare @name token that parsed as an
			// orphaned target rather than a value reference: see
			// operator_helpers.go's ResolveOperatorArgument doc comment on
			// the same condition. It contributes no dependency.
			if arg.Reference == nil {
				continue
			}
			for _, other := range locs {
				if other.Under(arg.Reference) {
					l = append(l, other)
				}
			}
		case OperatorCall:
			// Get dependencies from nested operator, preferring ev's
			// engine-local registry (see evaluateNestedOperator).
			// graft.EngineOf, not graft.GetEngine: see operator_helpers.go.
			nestedOp := OperatorForEngine(graft.EngineOf(ev), arg.Op())
			if _, ok := nestedOp.(graft.NullOperator); !ok {
				nestedDeps := nestedOp.Dependencies(ev, arg.Args(), locs, auto)
				l = append(l, nestedDeps...)
			}
		case Literal, List, Or, Negate, Addition, Subtraction, Multiplication, Division, Modulo,
			Equal, NotEqual, LessThan, LessThanOrEqual, GreaterThan, GreaterThanOrEqual,
			LogicalAnd, LogicalOr, RegexpMatch, EnvVar, BoshVar, VaultGroup, VaultChoice:
			// No dependencies for these types
		}
	}

	// append autogenerated dependencies (operator reference-type arguments)
	l = append(l, auto...)

	return l
}

func makeInt(val interface{}) int {
	if num, ok := val.(int); ok {
		return num
	}
	if num, ok := val.(int64); ok {
		return int(num)
	}
	return 0
}

func netSize(ipnet *net.IPNet) int {
	ones, bits := ipnet.Mask.Size()
	// Safely calculate shift value
	if bits <= ones {
		return 1 // Minimum network size
	}
	diff := bits - ones
	if diff >= 31 {
		return 1<<31 - 1 // Max int32 value
	}
	shift := uint(diff) // #nosec G115 - bounds checked above
	return 1 << shift
}

func abs(n int) int {
	if n < 0 {
		return -n
	}
	return n
}

// Run ...
func (IpsOperator) Run(ev *Evaluator, args []*Expr) (*Response, error) {
	DEBUG("running (( ips ... )) operation at $.%s", ev.Here)
	defer DEBUG("done with (( ips ... )) operation at $%s\n", ev.Here)

	if len(args) < 2 {
		return nil, fmt.Errorf("ips requires at least two arguments: 1) An IP or a CIDR and 2) an index")
	}

	vals := make([]interface{}, 0, len(args))

	for i, arg := range args {
		// Use ResolveOperatorArgument to support nested expressions
		val, err := ResolveOperatorArgument(ev, arg)
		if err != nil {
			DEBUG("     [%d]: resolution failed\n    error: %s", i, err)
			return nil, err
		}

		if val == nil {
			DEBUG("  arg[%d]: resolved to nil", i)
			return nil, fmt.Errorf("ips operator argument cannot be nil")
		}

		DEBUG("  arg[%d]: resolved to value (type: %T)", i, val)
		vals = append(vals, val)
		DEBUG("")
	}

	// Convert first argument to string (IP or CIDR)
	ipStr := fmt.Sprintf("%v", vals[0])

	ip, ipnet, err := net.ParseCIDR(ipStr)
	if err != nil {
		ip = net.ParseIP(ipStr)
		if ip == nil {
			DEBUG("     [0]: failed to parse IP or CIDR \"%s\": %s", ipStr, err)
			return nil, fmt.Errorf("first argument must be a valid IP or CIDR: %s", ipStr)
		}
	}

	start := makeInt(vals[1])

	if ipnet != nil {
		ip = ip.Mask(ipnet.Mask)
		netsize := netSize(ipnet)

		if abs(start) > netsize {
			return nil, fmt.Errorf("start index %d exceeds size of subnet %s", start, vals[0])
		}
		if start < 0 {
			start += netsize
		}
	}

	if len(args) == 2 {
		return &Response{
			Type:  Replace,
			Value: netutil.IPAdd(ip, start).String(),
		}, nil
	}
	count := makeInt(vals[2])
	if ipnet != nil {
		if start+count > netSize(ipnet) {
			return nil, fmt.Errorf("start index %d and count %d would exceed size of subnet %s", start, count, vals[0])
		}
	}
	lst := []interface{}{}
	for i := start; i < start+count; i++ {
		lst = append(lst, netutil.IPAdd(ip, i).String())
	}
	return &Response{
		Type:  Replace,
		Value: lst,
	}, nil
}

//nolint:gochecknoinits // Operator registration must happen at package load time
func init() {
	RegisterOp("ips", IpsOperator{})
}
